-- Phase 6 Area 2 golden tests: Reconciliation views (Customers, Customer detail, Controls, Assumptions and open items).
-- Hand values: ALDER annual prepaid 24,000 x 31 / 365 = 2,038.36 allocation, usage 1,575.76 ; CRESCENT / WILLOW 15th anchor 5,075.27 (14/30 + 17/31 of 5,000) ;
--   MERIDIAN expected 4,000.00 + 526.03 catch-up = 4,526.03 vs billed 4,000.00 ; CEDAR usage expected 8,291.20 vs billed 11,388.00 (over 3,096.80), weighted allowance 1,170,000 / 31 = 37,741.94 -> 37,742 ;
--   ZEPHYR usage expected net 852.60 = billed net 852.60 ; YARROW expected 3,074.28 billed 0 ; summary under 6,835.53 over 3,096.80 across 5 customers with a variance.
select test_name, expected, actual, (expected = actual) as pass from (
  select 'customers table rows' as test_name, '30' as expected, (select count(*) from public.ui_customers)::text as actual
  union all select 'summary: under / over / customers with a variance / unassigned', '6835.53/3096.80/5/1', (select round(under_billed, 2) || '/' || round(over_billed, 2) || '/' || customers_with_variance || '/' || unassigned_workspaces from public.ui_customers_summary)
  union all select 'summary platform allocation basis expected / billed', '93060.17/92534.14', (select round(plat_exp_alloc, 2) || '/' || round(plat_bill_alloc, 2) from public.ui_customers_summary)
  union all select 'summary platform invoice basis expected / billed', '72526.03/72000.00', (select round(plat_exp_inv, 2) || '/' || round(plat_bill_inv, 2) from public.ui_customers_summary)
  union all select 'summary usage expected / billed / under / over', '77944.60/74731.90/6309.50/3096.80', (select round(usage_exp, 2) || '/' || round(usage_bill, 2) || '/' || round(usage_under, 2) || '/' || round(usage_over, 2) from public.ui_customers_summary)
  union all select 'Alder platform (annual prepaid) allocation expected/billed and note', '2038.36/2038.36/Annual prepaid Sep 1', (select round(plat_exp_alloc, 2) || '/' || round(plat_bill_alloc, 2) || '/' || plat_note from public.ui_customers where customer = 'Alder Fieldworks')
  union all select 'Alder platform invoice basis (nothing billed in October)', '0.00', (select round(plat_exp_inv, 2)::text from public.ui_customers where customer = 'Alder Fieldworks')
  union all select 'Alder usage expected/billed', '1575.76/1575.76', (select round(usage_exp, 2) || '/' || round(usage_bill, 2) from public.ui_customers where customer = 'Alder Fieldworks')
  union all select 'Crescent 15th anchor allocation', '5075.27/5075.27', (select round(plat_exp_alloc, 2) || '/' || round(plat_bill_alloc, 2) from public.ui_customers where customer = 'Crescent Shore')
  union all select 'Willow 15th anchor allocation and unattributed usage', '5075.27/true', (select round(plat_exp_alloc, 2) || '/' || usage_unattributed from public.ui_customers where customer = 'Willow Passage')
  union all select 'Meridian platform expected / billed / under (allocation)', '4526.03/4000.00/526.03', (select round(plat_exp_alloc, 2) || '/' || round(plat_bill_alloc, 2) || '/' || round(plat_under_alloc, 2) from public.ui_customers where customer = 'Meridian Process Systems')
  union all select 'Meridian note mentions the catch-up', 'true', (select (plat_note like '%Includes $526.03 upgrade catch-up%')::text from public.ui_customers where customer = 'Meridian Process Systems')
  union all select 'Cedar usage expected / billed / over', '8291.20/11388.00/3096.80', (select round(usage_exp, 2) || '/' || round(usage_bill, 2) || '/' || round(usage_over, 2) from public.ui_customers where customer = 'Cedar Harbor Labs')
  union all select 'Zephyr usage matches after the approved credit', '852.60/852.60/$100.00 approved credit issued Nov 4', (select round(usage_exp, 2) || '/' || round(usage_bill, 2) || '/' || usage_note from public.ui_customers where customer = 'Zephyr Grove')
  union all select 'Yarrow expected / billed / under', '3074.28/0.00/3074.28', (select round(usage_exp, 2) || '/' || round(usage_bill, 2) || '/' || round(usage_under, 2) from public.ui_customers where customer = 'Yarrow Ridge')
  union all select 'customers with a variance flag', '5', (select count(*) from public.ui_customers where has_variance)::text
  union all select 'customers flagged needs info (Willow)', 'Willow Passage', (select string_agg(customer, ',') from public.ui_customers where has_needs_info)
  union all select 'unassigned workspace isolated row', 'pa_676b6b455e0887/49762/31', (select product_account_id || '/' || october_runs || '/' || october_records from public.ui_unassigned_workspace)
  union all select 'unassigned workspace appears in no customer row', '0', (select count(*) from public.ui_customers where flags like '%F-05%')::text
  union all select 'Cedar header ids', 'cus_c34b5d920c411f/639373/CT-639373/F-01', (select stripe_customer_id || '/' || ns_id || '/' || contract_ids || '/' || finding_ids from public.ui_customer_header where customer = 'Cedar Harbor Labs')
  union all select 'Cedar KPIs: platform revenue posted, usage accrual posted / expected / diff', '4076.71/11388.00/8291.20/3096.80',
        (select round(plat_revenue_posted, 2) || '/' || round(usage_accrual_posted, 2) || '/' || round(usage_accrual_expected, 2) || '/' || round(usage_accrual_diff, 2) from public.ui_customer_kpis k join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs')
  union all select 'Cedar contract versions', 'OF-2026-157,AM-OF-2026-157', (select string_agg(doc, ',' order by version_no) from public.ui_customer_versions v join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs')
  union all select 'Cedar amendment billing load missing', 'true', (select billing_load_missing::text from public.ui_customer_versions v join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs' and version_no = 2)
  union all select 'Cedar October allowance by day', 'Oct 1–15 · 30,000 × 15 days|Oct 16–31 · 45,000 × 16 days|Weighted allowance = 37,741.94, rounded once to 37,742 runs',
        (select string_agg(label, '|' order by ord, label) from public.ui_customer_allowance a join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs')
  union all select 'Cedar usage validation: days / duplicates / runs / allowance / overage', '31/0/58470/37742/20728', (select days_with_records || '/' || duplicate_records || '/' || total_runs || '/' || allowance_runs || '/' || overage_units from public.ui_customer_usage_validation v join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs')
  union all select 'Silver Current two product accounts aggregated (62 records over 31 days)', '2/31', (select accounts_verified || '/' || days_with_records from public.ui_customer_usage_validation v join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Silver Current')
  union all select 'Westhaven shows the repeated record', '1', (select duplicate_records::text from public.ui_customer_usage_validation v join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Westhaven Metrics')
  union all select 'Cedar invoices (Sep P, Oct P, Oct U, Nov P, Nov U)', '5', (select count(*) from public.ui_customer_invoices i join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs')::text
  union all select 'Cedar usage invoice amounts', '12243.20/11388.00', (select string_agg(round(amount, 2)::text, '/' order by issued) from public.ui_customer_invoices i join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs' and type = 'Usage')
  union all select 'Cedar has no credit notes', '0', (select count(*) from public.ui_customer_credit_notes n join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs')::text
  union all select 'Alder void credit note listed with no effect', 'Void/50.00', (select status || '/' || round(amount, 2) from public.ui_customer_credit_notes n join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Alder Fieldworks')
  union all select 'Cedar accounting trail (5 October journals)', '5', (select count(*) from public.ui_customer_gl_trail g join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs')::text
  union all select 'Cedar accrual journal amount', '11388.00', (select round(amount, 2)::text from public.ui_customer_gl_trail g join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs' and g.journal = 'JE-3670271955a1fc')
  union all select 'Cedar 1150 rollforward text', '12,243.20 − 12,243.20 + 11,388.00 = 11,388.00 posted', (select posted_text from public.ui_customer_rollforward r join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs' and ord = 1)
  union all select 'Cedar 2200 rollforward text', 'Cr 54.79 + Cr 4,000.00 − Dr 4,076.71 = Dr 21.92', (select posted_text from public.ui_customer_rollforward r join public.ui_customer_header h using (salesforce_account_id) where h.customer = 'Cedar Harbor Labs' and ord = 2)
  union all select 'controls: 19 rows, 18 pass, 1 pending (B4)', '19/18/B4', (select count(*) || '/' || count(*) filter (where status = 'pass') || '/' || string_agg(control_id, ',') filter (where status = 'pending') from public.ui_controls)
  union all select 'open items listed', '9', (select count(*) from public.ui_open_items)::text
  union all select 'open items: O-4 Zephyr resolved, others open', '8 open/1 resolved', (select count(*) filter (where status = 'Open') || ' open/' || count(*) filter (where status = 'Resolved') || ' resolved' from public.ui_open_items)
  union all select 'O-1 workspace runs and range', 'true', (select (what_we_know like '31 October records totaling 49,762 runs%' and exposure like 'Conditional: $390.48 to $19,904.80%')::text from public.ui_open_items where ref = 'O-1')
  union all select 'O-5 Meridian later-service $1,000', 'true', (select (exposure like '%$1,000.00%')::text from public.ui_open_items where ref = 'O-5')
  union all select 'assumptions listed', '12', (select count(*) from public.ui_assumptions)::text
  union all select 'A-7 cutoff text from the parameter table', 'Invoices issued by the Nov 11, 2026 6:00 PM MT cutoff are included. Later invoices are not.', (select assumption from public.ui_assumptions where ref = 'A-7')
  union all select 'snapshots fresh: customers and summary', '0', (select (select count(*) from ((select * from public.ui_customers except select * from public.ui_customers_live) union all (select * from public.ui_customers_live except select * from public.ui_customers)) a)::text)
) t;
